class Solution {
    public int countVowelPermutation(int n){
        long mod=1000000007L,a=1,e=1,i=1,o=1,u=1;
        for(int length=2;length<=n;length++){
            long nextA=(e+i+u)%mod,nextE=(a+i)%mod,nextI=(e+o)%mod,nextO=i,nextU=(i+o)%mod;
            a=nextA;
            e=nextE;
            i=nextI;
            o=nextO;
            u=nextU;
        }
        return (int)((a+e+i+o+u)%mod);
    }
}

